INSERT OR REPLACE INTO knowledge_vectors (vector_id, source_type, source_id, title, category, content_chunk, embedding_json, metadata_json) VALUES ('vec_seed_004', 'machine_spec', 'MC-CNC-01', 'คู่มือแก้ไข Error E-04 / Spindle Overload เครื่อง CNC', 'electrical', 'อาการ: เครื่อง CNC หยุดทำงานและฟ้องเตือน Error Code E-04 Spindle Overload\nสาเหตุ: มีเศษชิปโลหะติดขัดในร่อง Spindle Tool Clamping หรือโหลดตัดชิ้นงานกินลึกเกินค่า Feed Rate ที่กำหนด\nวิธีแก้ไข: 1. ทำความสะอาดกรวย Spindle และตรวจสอบแรงดันลม Unclamp (ต้องไม่ต่ำกว่า 6 bar) 2. รีเซ็ต Alarm ที่หน้าตู้คอนโทรล 3. ปรับลด Feed Rate และ Depth of Cut ลง 15%', '[0.0, 0.154, 0.1232, 0.0924, 0.0308, 0.0308, 0.0271, 0.0, 0.0308, 0.0308, 0.0308, 0.0308, 0.0308, 0.0, 0.0308, 0.0308, 0.0413, 0.0887, 0.0, 0.0308, 0.0688, 0.0308, 0.0, 0.0308, 0.0616, 0.081, 0.081, 0.0308, 0.0, 0.0924, 0.0795, 0.0308, 0.154, 0.0, 0.0616, 0.1876, 0.0308, 0.0, 0.0, 0.0308, 0.0, 0.0, 0.0308, 0.0308, 0.0308, 0.0308, 0.0308, 0.0616, 0.0, 0.0616, 0.0308, 0.0308, 0.0616, 0.0616, 0.0308, 0.1232, 0.0, 0.0981, 0.0308, 0.0, 0.0, 0.0924, 0.0308, 0.0924, 0.0308, 0.0616, 0.0924, 0.0308, 0.0616, 0.0, 0.0308, 0.0, 0.0924, 0.0308, 0.0, 0.0, 0.1232, 0.0, 0.0924, 0.0, 0.0616, 0.0616, 0.0616, 0.0616, 0.0308, 0.0616, 0.0616, 0.0924, 0.0308, 0.0616, 0.0924, 0.154, 0.0, 0.0616, 0.0, 0.0308, 0.0308, 0.0308, 0.0308, 0.0953, 0.0616, 0.0, 0.0852, 0.0996, 0.0308, 0.0, 0.0308, 0.0308, 0.0616, 0.0, 0.0616, 0.0308, 0.0, 0.0308, 0.0, 0.0, 0.0308, 0.0308, 0.154, 0.0616, 0.0, 0.0308, 0.0308, 0.0308, 0.0616, 0.0308, 0.0924, 0.0308, 0.0337, 0.0308, 0.0, 0.0308, 0.0616, 0.0308, 0.0, 0.0308, 0.0308, 0.0, 0.0308, 0.0924, 0.0, 0.0, 0.0616, 0.0308, 0.0616, 0.0924, 0.0, 0.0616, 0.0, 0.0, 0.0308, 0.0308, 0.0616, 0.154, 0.1592, 0.0645, 0.0, 0.0616, 0.0836, 0.0308, 0.0308, 0.0, 0.0, 0.1232, 0.0, 0.154, 0.0, 0.0, 0.0308, 0.0308, 0.0, 0.0616, 0.0616, 0.0308, 0.0924, 0.0616, 0.0, 0.0981, 0.0976, 0.0308, 0.0308, 0.1013, 0.0616, 0.0308, 0.0, 0.0, 0.0616, 0.0924, 0.0308, 0.0616, 0.0308, 0.1013,